from __future__ import absolute_import
from selenium.webdriver.common.by import By
from selenium.common.exceptions import ElementClickInterceptedException
from taf.selenium.sbts.pages import v24r3


class BtsBasicInfo(v24r3.BtsBasicInfo):
    """
    The class corresponding to BTS basic info on selenium_sbts web,
    all operations of BTS basic info will be implemented or added in it.
    """

    _BTS_VERSION_XPATH = "//span[@class='otx-product-sw-name']"

    _DISCONNECT_BUTTON_XPATH = '//button[@ng-reflect-text="Disconnect"]'
    _CONNECT_BUTTON_XPATH = '//button[@ng-reflect-text="Connect"]'

    _BTS_ID_XPATH = '//span[@class="p-element otx-product-bts-id"]'
    _LOAD_IMS2_INPUT_CSS = "ot-upload[ng-reflect-text='Load IMS2'] input"
    _LOAD_IMS2_INPUT_BUTTON = "//ot-upload[@ng-reflect-text='Load IMS2']//input"

    def get_bts_status(self, technology):
        tech_xpath = '//div[@class="cells-status-info" and text()="{}"]/parent::*/parent::*/span'.format(technology)
        return self.get_text_by_xpath(tech_xpath)

    def get_bts_version(self):
        return self.get_text_by_xpath(self._BTS_VERSION_XPATH)

    def connect_to_bts_if_disconnected(self, wait_bar_menu_timeout=30, timeout=1):
        """
        Connects to BTS if Connect button is available and waits for successful connection

        :param wait_bar_menu_timeout: time to wait for status bar menu button loaded after refresh; defaults to 30
        :type timeout: int or str
        :param timeout: time to wait for Connect/Disconnect button to be visible
        :type timeout: int

        """
        self.wait_for_visibility_by_xpath(xpath=self._BTS_VERSION_XPATH, timeout=wait_bar_menu_timeout)
        if self._can_be_connected_to_bts(timeout=timeout):
            self._reconnect_to_bts(timeout)

    def _can_be_connected_to_bts(self, timeout=1):
        """
        Checks in which state Connect/Disconnect button is in.
        :param timeout: time to wait for button state to be available
        :type timeout: int
        :return: True if button is in 'Connect' state, False otherwise
        :rtype: bool
        """
        return self.element_exists((By.XPATH, self._CONNECT_BUTTON_XPATH), timeout=timeout)

    def _reconnect_to_bts(self, timeout):
        """
        Reconnect with BTS by clicking connect (if it is disconnected),
        when status bar menu button contains dropdown list.
        :param timeout: Time to wait for particular steps being performed.
        :type timeout: int
        """

        try:
            self.click_enabled_element((By.XPATH, self._CONNECT_BUTTON_XPATH), timeout=timeout)
        except ElementClickInterceptedException:
            self.click_enabled_element((By.XPATH, self._CONNECT_BUTTON_XPATH), timeout=timeout)

        self.wait_for_visibility_by_xpath(self._DISCONNECT_BUTTON_XPATH, timeout=timeout)

    def load_ims2(self, file_path, timeout):
        self.load_file_from_hidden_button(self._LOAD_IMS2_INPUT_CSS, self._LOAD_IMS2_INPUT_BUTTON, file_path, timeout)
        self._until(lambda _: '-' not in self.get_bts_version(), timeout)

    def get_bts_id(self):
        bts_id = self.get_text_by_xpath(self._BTS_ID_XPATH)
        return bts_id.lstrip("MRBTS ID:").strip()
